import React from 'react';

interface TabsProps {
    activeTab: 'calc' | 'info';
    onChange: (tab: 'calc' | 'info') => void;
}

export const Tabs: React.FC<TabsProps> = ({ activeTab, onChange }) => {
    return (
        <div className="flex bg-slate-100 p-1 rounded-xl mb-8 w-fit mx-auto">
            <button
                onClick={() => onChange('calc')}
                className={`flex items-center gap-2 px-6 py-2.5 rounded-lg text-sm font-bold transition-all ${
                    activeTab === 'calc' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'
                }`}
            >
                Вычисления
            </button>
            <button
                onClick={() => onChange('info')}
                className={`flex items-center gap-2 px-6 py-2.5 rounded-lg text-sm font-bold transition-all ${
                    activeTab === 'info' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'
                }`}
            >
                Методы и формулы
            </button>
        </div>
    );
};
